import logging
from typing import Callable

from ..exception import CannotAddNotificationClient
from ..wts.egate import Egate
from .importer import DotClientImporter, NonDotClientImporter


def catch_client_errors(func: Callable) -> Callable:
    """Decorator to disable exceptions from client libraries."""

    def wrapper(*args, **kwargs):
        """Wrapper method."""
        try:
            return func(*args, **kwargs)
        except CannotAddNotificationClient:
            raise
        except Exception as e:
            log = logging.getLogger(__name__)
            log.debug(
                f"It was not possible to initialize client library because of {e}"
            )

    return wrapper


class Notifier:
    """Class responsible for client notification."""

    def __init__(self):
        self._clients = {}

    @property
    def clients(self) -> dict:
        """Returns notification clients there were registered."""
        return self._clients

    @catch_client_errors
    def egate_created(self, egate: Egate, alias: str, *args) -> None:
        """Creates client objects and send notification about new egate object.

        :param Egate egate: Egate object provided by the package interface.
        :param string alias: Alias provided by the package interface.

        Provided arguments are list of libraries (each represented by string) taken as clients that have to be notify about new egate instance.
        """
        if alias in self._clients:
            raise CannotAddNotificationClient(
                "Provided alias exists and cannot be overridden. Please execute teardown method."
            )
        self._clients[alias] = []
        for each in args:
            client = self._import_client(each)
            if not client or not hasattr(client, "egate_created"):
                continue
            client.egate_created(egate, alias)
            self._clients[alias].append(client)
        if not self._clients[alias]:
            self._clients.pop(alias)

    @catch_client_errors
    def egate_deleted(self, alias: str) -> None:
        """Sends notification about deleted egate and deletes related clients. Egate and clients are identified by the alias.

        :param string alias: Alias provided by the package interface.
        """
        if alias not in self._clients:
            return
        for each in self._clients[alias]:
            if not hasattr(each, "egate_deleted"):
                continue
            each.egate_deleted(alias)
        self._clients.pop(alias)

    def _import_client(self, path: str) -> object:
        if "." in path:
            return DotClientImporter().import_client(path)
        return NonDotClientImporter().import_client(path)
